-- BranCHAT Web 版の D1（索引）。中身（会話・版・画像・設定）は R2 に置く。uid はメールアドレスの SHA-256 の先頭 32 桁
CREATE TABLE IF NOT EXISTS users(uid TEXT PRIMARY KEY, email TEXT NOT NULL, created_at INTEGER, last_seen INTEGER, terms_ver INTEGER DEFAULT 0, terms_at INTEGER);
CREATE TABLE IF NOT EXISTS convs(uid TEXT NOT NULL, id TEXT NOT NULL, title TEXT, updated_at INTEGER, size INTEGER DEFAULT 0, deleted INTEGER DEFAULT 0, PRIMARY KEY(uid,id));
CREATE TABLE IF NOT EXISTS revs(uid TEXT NOT NULL, id TEXT NOT NULL, rev INTEGER NOT NULL, saved_at INTEGER, size INTEGER DEFAULT 0, title TEXT, PRIMARY KEY(uid,id,rev));
CREATE TABLE IF NOT EXISTS imgs(uid TEXT NOT NULL, id TEXT NOT NULL, size INTEGER DEFAULT 0, type TEXT, created_at INTEGER, PRIMARY KEY(uid,id));
CREATE TABLE IF NOT EXISTS kv(uid TEXT NOT NULL, name TEXT NOT NULL, updated_at INTEGER, size INTEGER DEFAULT 0, PRIMARY KEY(uid,name));
